,buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengelose",args={"rwnpc50"}}}},autoResult1={{type="doc",args={"CYN他身法很是灵活，你一时大意就要让他逃走，好在凌云赶到，一举将他擒下。NOR"}},{type="addobject",args={"rwnpc48a"}},{type="change",args={"rwnpc50","rwnpc50a"}}},autoCondition2={relation="and",conditions={{type="challengewin",args={"rwnpc50"}}}},autoResult2={{type="doc",args={"CYN他不敌于你，很快就被你擒住。NOR"}},{type="addobject",args={"rwnpc48a"}},{type="change",args={"rwnpc50","rwnpc50a"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc50a={id="rwnpc50a",baseId="rwnpc50",combatid={1,100214},name="齐荆",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL齐荆：要杀要剐随你们便！NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL齐荆：阿望！雀儿！不要求他们，没什么大不了的！NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"314010",3}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc51={id="rwnpc51",baseId="rwnpc51",combatid={1,1001},name="何望",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"314011",1}},{type="doc",args={"YEL何望：求你们不要抓走齐大哥！我们可以把所有东西都还给你们！NOR"}},{type="refresh",args={}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc52={id="rwnpc52",baseId="rwnpc52",combatid={1,1001},name="雀儿",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"314012",1}},{type="doc",args={"YEL雀儿：是雀儿想要新衣服，齐大哥为了给雀儿买新衣服才去偷东西的，你们要抓就抓雀儿吧！NOR"}},{type="refresh",args={}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc53={id="rwnpc53",baseId="rwnpc53",combatid={1,1001},name="文柳",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL文柳：我本想趁着春节替人写对联，赚些许小钱，奈何这些恶霸不时前来索要银钱，我……唉……NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"314013",4}},{type="doc",args={"YEL文柳：多谢少侠出手相助，文某感激不尽。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL文柳：观少侠武艺超绝，且侠肝义胆。反顾文某，一把年纪，然一事无成，实在羞愧。NOR"}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL文柳：说起当年，我也曾意气扬扬，壮志满怀地赴京赶考。然临考之前，撞见一群高门贵子肆意凌虐寒门子弟，我一时义愤填膺，难以容忍，遂出言制止，竟因此为他人所衔恨。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL文柳：及临考之日，护卫竟声称在我身上搜出作弊小抄，主考官径直将我赶出考场，且永禁我再入考场。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL文柳：唉……少侠觉得，我当初之举，是对是错？NOR"}},{type="showbutton",args={4,1}},{type="showbutton",args={5,1}}},caozuoName4="就当如此",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL文柳：少侠之潇洒，真令我钦佩不已。或许重返昔日，我亦会作同般抉择。我或也当脱出往昔之囿，天地浩渺无垠，当另有他途可循。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL文柳：少侠，就此别过。NOR"}},{type="outobject",args={"rwnpc53"}}},caozuoName5="当审时度势",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL文柳：唉……或许少侠所言才是对的，当年是我太过莽撞冲动，才酿此后果。可若当时只作袖手之态，冷眼旁观，我又如何蒙混得过这颗心？NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL文柳：少侠，就此别过吧。NOR"}},{type="outobject",args={"rwnpc53"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"314013",3}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc54={id="rwnpc54",baseId="rwnpc54",combatid={1,100215},name="恶霸",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL恶霸：大过年的我就放你一马，你少多管闲事！NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL恶霸：就这点本事还想学人逞英雄？赶紧滚！NOR"}}},caozuoName3="制伏",buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="challenge",args={"rwnpc54"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengelose",args={"rwnpc54"}}}},autoResult1={{type="doc",args={"CYN双拳难敌四手，你一时落于下风。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="challengewin",args={"rwnpc54"}}}},autoResult2={{type="gaintab",args={"314013",3}},{type="doc",args={"CYN这三个恶霸都不是你的对手，一见形势不对就一溜烟的逃跑了。NOR"}},{type="outobject",args={"rwnpc54"}},{type="outobject",args={"rwnpc55"}},{type="outobject",args={"rwnpc56"}},{type="refresh",args={}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc55={id="rwnpc55",baseId="rwnpc55",combatid={1,100215},name="恶霸",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL恶霸：起开！有你什么事啊？NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc56={id="rwnpc56",baseId="rwnpc56",combatid={1,100215},name="恶霸",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL恶霸：不长眼的东西，小心连你一块揍！NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc57={id="rwnpc57",baseId="rwnpc57",combatid={1,1001},name="许达",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL许达：少侠看起来对此地颇为熟稔，不知少侠可认得沈二娘？是否知晓沈二娘身在何处？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL许达：不瞒少侠，在下乃是沈二娘夫君的故交。受其嘱托，要将些许物事交予沈二娘。NOR"}},{type="showbutton",args={3,1}}},caozuoName3="指路",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"314014",1}},{type="doc",args={"YEL许达：多谢少侠告知。NOR"}},{type="outobject",args={"rwnpc57"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc57a={id="rwnpc57a",baseId="rwnpc57",combatid={1,1001},name="许达",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL许达：唉……实言相告，在下是无颜去见沈二娘。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL许达：我与她夫魏戎机缘巧合之下结识，志趣相契，遂结拜为兄弟。后来，我遭仇家围追剿杀，幸得魏戎舍命相护，吾方能苟延残喘至今。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL许达：彼时，他乔装作我的模样，代我引开那追兵……此后，我多方探寻，皆不闻其讯息，恐已遭歹人毒手。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL许达：魏戎临行之际，托我将这包裹交予沈二娘，且传语于她：魏戎昔年骤然离家，心中常怀愧疚。多年所积之财，尽付于沈二娘，望二娘另觅良人再嫁。此生，魏戎负她良多，唯待来世再报此恩。NOR"}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"314014",3}},{type="doc",args={"YEL许达：唉……我实在无颜面对她，还望少侠替我将这包裹转交吧。NOR"}},{type="itemin",args={"2025cjdj16",1}},{type="tips",args={"包裹*1"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL许达：唉……我实在无颜面对她，还望少侠替我将这包裹转交吧。NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"314014",5}}}},autoResult1={{type="outobject",args={"rwnpc57a"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc58={id="rwnpc58",baseId="rwnpc58",combatid={1,1001},name="沈二娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL沈二娘：都过年了，那死鬼还不回来。NOR"}}},caozuoName2="给予",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"314014",4}},{type="doc",args={"CYN沈二娘有些疑惑的打开包裹，包裹里是些银子、发簪首饰和女子衣装。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL沈二娘：少侠这是何意？NOR"}},{type="itemout",args={"2025cjdj16",1}},{type="tips",args={"失去包裹*1"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="showbutton",args={4,1}},{type="showbutton",args={5,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL沈二娘：少侠这是何意？NOR"}}},caozuoName4="告知真相",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="gaintab",args={"314014",5}},{type="doc",args={"CYN沈二娘沉默了许久NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL沈二娘：怕是少侠认错了吧，我昨日梦见魏郎，他说他很快就会回家了。NOR"}},{type="change",args={"rwnpc58","rwnpc58a"}}},caozuoName5="隐瞒真相",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="gaintab",args={"314014",5}},{type="doc",args={"YEL沈二娘：这个死鬼，不要以为他送点东西就可以让我心软，等他回家我照样要他好看！NOR"}},{type="change",args={"rwnpc58","rwnpc58b"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"314014",3}},{type="itemgreater",args={"2025cjdj16",0}}}},autoResult1={{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc58a={id="rwnpc58a",baseId="rwnpc58",combatid={1,1001},name="沈二娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL沈二娘：少侠别说了，你应该是弄错了。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc58b={id="rwnpc58b",baseId="rwnpc58",combatid={1,1001},name="沈二娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL沈二娘：算他还有点良心。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},a