nditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc60={id="rwnpc60",baseId="rwnpc60",combatid={1,1001},name="施海",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL施海：这里怎么这么多官府之人？NOR"}}},caozuoName2="给予",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"314015",2}},{type="doc",args={"YEL施海：又是周迹？这小子怎么阴魂不散的……NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL施海：这……来都来了，大过年的，我也不好拒绝他，我就勉为其难的收下吧。NOR"}},{type="itemout",args={"2025cjdj17",1}},{type="tips",args={"失去食盒*1"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"314015",3}},{type="doc",args={"YEL施海：嗐，我们不过是一个小山寨，前不久官府攻山，我趁乱逃到此处？NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL施海：周迹曾经救过我家寨主性命，寨主为报救命之恩，便将他留在身旁。只是那周迹，着实毫无为山贼的资质。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL施海：我们抢人，他放人；带他收粮，他跟人论起耕种之事……奈何他是寨主的救命恩人，寨主重义气，不愿杀他，只能把他劝回家种地了。NOR"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL施海：这里这么多官府之人，我不宜久留，先告辞了。NOR"}},{type="outobject",args={"rwnpc60"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"314015",1}},{type="itemgreater",args={"2025cjdj17",0}}}},autoResult1={{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4